begin;
create extension if not exists pgcrypto;
create type public.member_role as enum ('owner','project_admin','designer','supplier_manager','supplier_engineer','reviewer');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,name text not null default '',language text not null default 'fr-CA' check(language in ('fr-CA','en','zh-CN')),timezone text not null default 'America/Toronto',status text not null default 'active' check(status in ('active','suspended')),created_at timestamptz not null default now());
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 160),created_at timestamptz not null default now());
create table public.organization_memberships(organization_id uuid references public.organizations on delete cascade,user_id uuid references public.profiles on delete cascade,role public.member_role not null,active boolean not null default true,primary key(organization_id,user_id));
create table public.suppliers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,name text not null,country text not null,language text not null check(language in ('fr-CA','en','zh-CN')),contacts text not null default '',status text not null default 'active' check(status in ('active','inactive')),unique(organization_id,id));
create table public.supplier_notes(organization_id uuid not null,supplier_id uuid primary key,internal_notes text not null default '',foreign key(organization_id,supplier_id) references public.suppliers(organization_id,id));
create table public.supplier_memberships(organization_id uuid not null,supplier_id uuid not null,user_id uuid not null,active boolean not null default true,can_invite boolean not null default false,primary key(supplier_id,user_id),foreign key(organization_id,supplier_id) references public.suppliers(organization_id,id),foreign key(organization_id,user_id) references public.organization_memberships(organization_id,user_id));
create table public.projects(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,code text not null check(code ~ '^[A-Za-z0-9_-]{1,40}$'),name text not null check(length(name) between 1 and 160),description text not null default '',status text not null default 'active' check(status in ('active','paused','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),unique(organization_id,code));
create table public.project_suppliers(organization_id uuid not null,project_id uuid not null,supplier_id uuid not null,primary key(project_id,supplier_id),foreign key(organization_id,project_id) references public.projects(organization_id,id),foreign key(organization_id,supplier_id) references public.suppliers(organization_id,id));
create table public.project_memberships(organization_id uuid not null,project_id uuid not null,user_id uuid not null,role public.member_role not null check(role<>'owner'),supplier_id uuid,active boolean not null default true,primary key(project_id,user_id),foreign key(organization_id,project_id) references public.projects(organization_id,id),foreign key(organization_id,user_id) references public.organization_memberships(organization_id,user_id),foreign key(project_id,supplier_id) references public.project_suppliers(project_id,supplier_id),check((role in ('supplier_manager','supplier_engineer'))=(supplier_id is not null)));
create table public.invitations(id uuid primary key default gen_random_uuid(),organization_id uuid not null,project_id uuid not null,supplier_id uuid,email text not null,role public.member_role not null check(role<>'owner'),token_hash text not null unique,created_by uuid not null references public.profiles,created_at timestamptz not null default now(),expires_at timestamptz not null,accepted_at timestamptz,revoked_at timestamptz,foreign key(organization_id,project_id) references public.projects(organization_id,id),foreign key(project_id,supplier_id) references public.project_suppliers(project_id,supplier_id),check((role in ('supplier_manager','supplier_engineer'))=(supplier_id is not null)));
create table public.audit_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,actor_id uuid not null references public.profiles,action text not null,resource_id uuid,created_at timestamptz not null default now());
create table public.outbox(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,event_type text not null,payload jsonb not null,created_at timestamptz not null default now(),delivered_at timestamptz,idempotency_key uuid not null unique default gen_random_uuid());
create index on public.organization_memberships(user_id);
create index on public.project_memberships(user_id,project_id);
create index on public.supplier_memberships(user_id,supplier_id);
create index on public.projects(organization_id,updated_at desc);
create index on public.invitations(organization_id,created_at desc);
create index on public.audit_events(organization_id,created_at desc);
create index on public.outbox(created_at) where delivered_at is null;
create function public.active_user() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=auth.uid() and status='active')$$;
create function public.org_member(o uuid) returns boolean language sql stable security definer set search_path='' as $$select public.active_user() and exists(select 1 from public.organization_memberships where organization_id=o and user_id=auth.uid() and active)$$;
create function public.is_owner(o uuid) returns boolean language sql stable security definer set search_path='' as $$select public.org_member(o) and coalesce(auth.jwt()->>'aal','')='aal2' and exists(select 1 from public.organization_memberships where organization_id=o and user_id=auth.uid() and active and role='owner')$$;
create function public.project_access(p uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.projects pr where pr.id=p and public.org_member(pr.organization_id) and (public.is_owner(pr.organization_id) or exists(select 1 from public.project_memberships pm where pm.project_id=p and pm.user_id=auth.uid() and pm.active and (pm.role<>'project_admin' or coalesce(auth.jwt()->>'aal','')='aal2') and (pm.supplier_id is null or exists(select 1 from public.supplier_memberships sm join public.suppliers s on s.id=sm.supplier_id join public.project_suppliers ps on ps.project_id=p and ps.supplier_id=sm.supplier_id where sm.supplier_id=pm.supplier_id and sm.user_id=auth.uid() and sm.active and s.status='active')))))$$;
create function public.project_admin(p uuid) returns boolean language sql stable security definer set search_path='' as $$select public.project_access(p) and coalesce(auth.jwt()->>'aal','')='aal2' and (exists(select 1 from public.projects where id=p and public.is_owner(organization_id)) or exists(select 1 from public.project_memberships where project_id=p and user_id=auth.uid() and role='project_admin' and active))$$;
create function public.internal_member(o uuid) returns boolean language sql stable security definer set search_path='' as $$select public.org_member(o) and exists(select 1 from public.organization_memberships where organization_id=o and user_id=auth.uid() and role in ('owner','project_admin','designer','reviewer') and active)$$;
create function public.on_auth_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,name) values(new.id,coalesce(new.raw_user_meta_data->>'name',''));return new;end$$;
create trigger auth_user_created after insert on auth.users for each row execute function public.on_auth_user();
insert into public.profiles(id,name) select id,coalesce(raw_user_meta_data->>'name','') from auth.users on conflict do nothing;
-- No direct writes to access-control tables: all mutations are checked transactional RPCs.
do $$declare t text;begin foreach t in array array['profiles','organizations','organization_memberships','suppliers','supplier_notes','supplier_memberships','projects','project_suppliers','project_memberships','invitations','audit_events','outbox'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);end loop;end$$;
create policy profiles_self on public.profiles for select to authenticated using(id=auth.uid());
create policy org_read on public.organizations for select to authenticated using(public.org_member(id));
create policy membership_read on public.organization_memberships for select to authenticated using(public.is_owner(organization_id) or user_id=auth.uid());
create policy projects_read on public.projects for select to authenticated using(public.project_access(id));
create policy supplier_read on public.suppliers for select to authenticated using(public.internal_member(organization_id) or (public.org_member(organization_id) and exists(select 1 from public.supplier_memberships sm where sm.supplier_id=id and sm.user_id=auth.uid() and sm.active)));
create policy notes_read on public.supplier_notes for select to authenticated using(public.is_owner(organization_id));
create policy supplier_members_read on public.supplier_memberships for select to authenticated using(public.is_owner(organization_id) or user_id=auth.uid());
create policy project_suppliers_read on public.project_suppliers for select to authenticated using(public.project_admin(project_id) or (public.project_access(project_id) and exists(select 1 from public.supplier_memberships sm where sm.user_id=auth.uid() and sm.supplier_id=project_suppliers.supplier_id and sm.active)));
create policy project_members_read on public.project_memberships for select to authenticated using(public.project_admin(project_id) or user_id=auth.uid());
create policy invitations_read on public.invitations for select to authenticated using(public.project_admin(project_id));
create policy audit_read on public.audit_events for select to authenticated using(public.is_owner(organization_id));
-- Outbox intentionally has no client-readable policy.
create function public.record_event(o uuid,a text,r uuid) returns void language plpgsql security definer set search_path='' as $$begin insert into public.audit_events(organization_id,actor_id,action,resource_id) values(o,auth.uid(),a,r);insert into public.outbox(organization_id,event_type,payload) values(o,a,jsonb_build_object('resource_id',r,'actor_id',auth.uid()));end$$;
create function public.update_preferences(n text,l text,t text) returns void language plpgsql security definer set search_path='' as $$begin if not public.active_user() or length(n) not between 1 and 120 or l not in ('fr-CA','en','zh-CN') or not exists(select 1 from pg_timezone_names where name=t) then raise exception 'Forbidden or invalid preferences' using errcode='42501';end if;update public.profiles set name=n,language=l,timezone=t where id=auth.uid();end$$;
create function public.save_project(o uuid,p uuid,c text,n text,d text,s text) returns uuid language plpgsql security definer set search_path='' as $$declare result uuid;begin if (p is null and not public.is_owner(o)) or (p is not null and not public.project_admin(p)) then raise exception 'Forbidden' using errcode='42501';end if;if p is null then insert into public.projects(organization_id,code,name,description,status) values(o,c,n,d,s) returning id into result;else update public.projects set code=c,name=n,description=d,status=s,updated_at=now() where id=p and organization_id=o returning id into result;end if;if result is null then raise exception 'Not found';end if;perform public.record_event(o,'project.saved',result);return result;end$$;
create function public.save_supplier(o uuid,s uuid,n text,c text,l text,ct text,nt text,st text) returns uuid language plpgsql security definer set search_path='' as $$declare result uuid;begin if not public.is_owner(o) then raise exception 'Forbidden' using errcode='42501';end if;if s is null then insert into public.suppliers(organization_id,name,country,language,contacts,status) values(o,n,c,l,ct,st) returning id into result;else update public.suppliers set name=n,country=c,language=l,contacts=ct,status=st where id=s and organization_id=o returning id into result;end if;if result is null then raise exception 'Not found';end if;insert into public.supplier_notes(organization_id,supplier_id,internal_notes) values(o,result,nt) on conflict(supplier_id) do update set internal_notes=excluded.internal_notes;perform public.record_event(o,'supplier.saved',result);return result;end$$;
create function public.link_supplier(p uuid,s uuid) returns void language plpgsql security definer set search_path='' as $$declare o uuid;begin select organization_id into o from public.projects where id=p;if not public.project_admin(p) then raise exception 'Forbidden' using errcode='42501';end if;insert into public.project_suppliers(organization_id,project_id,supplier_id) values(o,p,s) on conflict do nothing;perform public.record_event(o,'project.supplier.linked',s);end$$;
create function public.create_invitation(p uuid,s uuid,e text,r public.member_role,h text,days integer) returns uuid language plpgsql security definer set search_path='' as $$declare o uuid; i uuid;begin select organization_id into o from public.projects where id=p;if not public.project_admin(p) then raise exception 'Forbidden' using errcode='42501';end if;if r='owner' or days not between 1 and 14 or length(h)<>64 then raise exception 'Invalid invitation';end if;insert into public.invitations(organization_id,project_id,supplier_id,email,role,token_hash,created_by,expires_at) values(o,p,s,lower(trim(e)),r,h,auth.uid(),now()+make_interval(days=>days)) returning id into i;perform public.record_event(o,'invitation.created',i);return i;end$$;
create function public.accept_invitation(h text) returns uuid language plpgsql security definer set search_path='' as $$declare i public.invitations;begin if not public.active_user() or coalesce((auth.jwt()->>'email_verified')::boolean,false)=false and not exists(select 1 from auth.users where id=auth.uid() and email_confirmed_at is not null) then raise exception 'Verified account required' using errcode='42501';end if;select * into i from public.invitations where token_hash=h for update;if i.id is null or i.accepted_at is not null or i.revoked_at is not null or i.expires_at<=now() or lower(i.email)<>lower(auth.jwt()->>'email') then raise exception 'Invalid invitation' using errcode='42501';end if;if i.role='project_admin' and coalesce(auth.jwt()->>'aal','')<>'aal2' then raise exception 'MFA required' using errcode='42501';end if;insert into public.organization_memberships(organization_id,user_id,role) values(i.organization_id,auth.uid(),i.role) on conflict do nothing;if i.supplier_id is not null then insert into public.supplier_memberships(organization_id,supplier_id,user_id) values(i.organization_id,i.supplier_id,auth.uid()) on conflict do nothing;end if;insert into public.project_memberships(organization_id,project_id,user_id,role,supplier_id) values(i.organization_id,i.project_id,auth.uid(),i.role,i.supplier_id) on conflict(project_id,user_id) do nothing;update public.invitations set accepted_at=now() where id=i.id;perform public.record_event(i.organization_id,'invitation.accepted',i.id);return i.project_id;end$$;
create function public.revoke_invitation(i uuid) returns void language plpgsql security definer set search_path='' as $$declare v public.invitations;begin select * into v from public.invitations where id=i for update;if v.id is null or not public.project_admin(v.project_id) then raise exception 'Forbidden' using errcode='42501';end if;update public.invitations set revoked_at=now() where id=i;perform public.record_event(v.organization_id,'invitation.revoked',i);end$$;
create function public.set_project_member(p uuid,u uuid,r public.member_role,a boolean) returns void language plpgsql security definer set search_path='' as $$declare m public.project_memberships;begin if not public.project_admin(p) or r='owner' then raise exception 'Forbidden' using errcode='42501';end if;select * into m from public.project_memberships where project_id=p and user_id=u for update;if m.user_id is null or (r in ('supplier_manager','supplier_engineer'))<>(m.supplier_id is not null) then raise exception 'Invalid membership';end if;update public.project_memberships set role=r,active=a where project_id=p and user_id=u;perform public.record_event(m.organization_id,'project.membership.changed',u);end$$;
-- Explicitly revoke PostgreSQL's default PUBLIC execute permission, including helper RPCs.
revoke execute on all functions in schema public from public,anon,authenticated;
grant execute on function public.active_user(),public.org_member(uuid),public.is_owner(uuid),public.project_access(uuid),public.project_admin(uuid),public.internal_member(uuid),public.update_preferences(text,text,text),public.save_project(uuid,uuid,text,text,text,text),public.save_supplier(uuid,uuid,text,text,text,text,text,text),public.link_supplier(uuid,uuid),public.create_invitation(uuid,uuid,text,public.member_role,text,integer),public.accept_invitation(text),public.revoke_invitation(uuid),public.set_project_member(uuid,uuid,public.member_role,boolean) to authenticated;
commit;
